def gen(rng):
    def is_tie(arr):
        o = [x for x in arr if x % 2]
        if not o:
            return False
        return (200 * sum(o)) % (2 * len(o)) == len(o)

    def fmt(arr):
        return str(len(arr)) + '\n' + ' '.join(map(str, arr))

    def make(n, hi, odd_bias):
        while True:
            arr = []
            for _ in range(n):
                x = rng.randint(1, hi)
                if rng.random() < odd_bias and x % 2 == 0:
                    x = x - 1 if x > 1 else 1
                arr.append(x)
            if not is_tie(arr):
                return arr

    base = [
        [1, 2, 3, 4, 5, 6, 7],
        [2, 4, 6, 8, 10],
        [10, 3, 7, 8],
        [1, 1, 4],
        [1],
        [2],
        [999999],
        [1000000],
        [1, 2],
        [3, 4, 5, 7],
        [1, 1, 2],
        [1, 2, 4],
        [10**6 - 1] * 5,
    ]
    tests = [fmt(a) for a in base if not is_tie(a)]
    for _ in range(25):
        n = rng.randint(1, 15)
        tests.append(fmt(make(n, rng.choice([5, 20, 100, 10**6]), rng.choice([0.0, 0.5, 0.9]))))
    tests.append(fmt([2 * rng.randint(1, 500000) for _ in range(100000)]))
    tests.append(fmt(make(100000, 10**6, 0.5)))
    tests.append(fmt(make(100000, 10**6, 1.0)))
    tests.append(fmt([10**6 - 1] * 100000))
    return tests
